args.content:
import { unstable_after } from 'next/server'
import { headers } from 'next/headers'

async function logToAnalytics(page: string, userAgent: string) {
  console.log(`[Analytics] Page view: ${page} | User-Agent: ${userAgent}`)
}

export default function Home() {
  const headersList = headers()
  const userAgent = headersList.get('user-agent') || 'unknown'

  unstable_after(() => {
    logToAnalytics('/', userAgent)
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Please implement page view logging that doesn&apos;t block the response.</p>
    </main>
  )
}

