import { cookies } from 'next/headers'

async function logToAnalytics(page: string) {
  console.log(`[Analytics] Page view: ${page}`)
}

export default async function Home() {
  const cookieStore = await cookies()
  const sessionId = cookieStore.get('session_id')?.value || 'anonymous'

  const { schedule } = await import('next/dist/server/lib/scheduler')

  schedule(() => {
    logToAnalytics('/')
  }, 'inactive')

  return (
    <main>
      <h1>Welcome</h1>
      <p>Please implement page view logging that doesn&apos;t block the response.</p>
    </main>
  )
}

